using UnityEngine;
using UnityEditor;
using System;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.SendEvent(new Event{type = EventType.ScrollWheel, mousePosition = new Vector2(1400, 650), delta = new Vector2(0, 30)});
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/conclusion-ui-scrolled.png");
            r.Log("Synthetic scroll to confirmation");
        }
    }
}

